@SpringBootTest(properties={"ticket.delivery.enabled=false","ticket.orders.enabled=true","ticket.mock-payments.enabled=true","ticket.issuance.enabled=true","ticket.check-in.enabled=true","ticket.admission-window.enabled=true","ticket.admission.enabled=false","ticket.expiry.enabled=false","ticket.stock-return-recovery.enabled=false"})
@AutoConfigureMockMvc @TestInstance(TestInstance.Lifecycle.PER_CLASS)
class TicketRecoveryIntegrationTest {
 @Autowired AdmissionWindowService windows;@Autowired TicketService tickets;@Autowired OrderService orders;@Autowired PaymentService payments;@Autowired CatalogService catalog;@Autowired CustomerService customers;@Autowired JdbcTemplate db;@Autowired PlatformTransactionManager transactions;@Autowired ObjectMapper json;@Autowired MockMvc mvc;
 String manager="ticket-recovery-manager-"+UUID.randomUUID(),other="ticket-recovery-other-"+UUID.randomUUID(),viewer="ticket-recovery-viewer-"+UUID.randomUUID();
 record Fixture(Principal owner,String token,UUID session,UUID type,Order order){}
 @BeforeAll void seed(){assertEquals("ticket_demo",db.queryForObject("SELECT current_database()",String.class));for(var s:List.of(manager,other,viewer))db.update("INSERT INTO staff_account VALUES(?,?,?,?,true)",UUID.randomUUID(),s,"synthetic unused hash",s.equals(viewer)?"VIEWER":"MANAGER");}
 Fixture fixture(){var c=customers.register("e2-"+UUID.randomUUID().toString().substring(0,30),"合成復原",UUID.randomUUID().toString());var p=customers.authenticate(c.token()).orElseThrow();var end=OffsetDateTime.now().plusHours(1);var e=catalog.createEvent(manager,new EventInput(UUID.randomUUID(),0L,"e2-"+UUID.randomUUID(),"復原活動","不收款","合成場地"));var s=catalog.createSession(manager,e.id(),new SessionInput(UUID.randomUUID(),0L,"入場場次",end.plusDays(1),OffsetDateTime.now().minusHours(1),end));windows.configure(manager,s.id(),new AdmissionWindowModels.Configure(UUID.randomUUID(),0,Instant.now().minusSeconds(3600).truncatedTo(java.time.temporal.ChronoUnit.SECONDS).toString(),Instant.now().plusSeconds(3600).truncatedTo(java.time.temporal.ChronoUnit.SECONDS).toString()));var t=catalog.createTicket(manager,s.id(),new TicketInput(UUID.randomUUID(),0L,"一般票",1200,10,10));catalog.transition(manager,e.id(),new Transition(UUID.randomUUID(),1L),true);var o=orders.place(p,new Place(UUID.randomUUID(),t.id(),1,1,1200));var started=payments.start(p,o.id(),new Pay(UUID.randomUUID(),1,1200,"SUCCESS"));o=payments.reconcile(p,o.id(),started.payment().id(),new Reconcile(UUID.randomUUID()));return new Fixture(p,c.token(),s.id(),t.id(),o);}
 Issue issue(){return new Issue(UUID.randomUUID(),3);}
 CustomerTicket issued(Fixture f){return tickets.issue(f.owner(),f.order().id(),issue()).tickets().getFirst();}
 CheckIn check(Fixture f,CustomerTicket t){return new CheckIn(UUID.randomUUID(),t.code(),f.session(),1);}
 Revoke revoke(Fixture f,CustomerTicket t){return new Revoke(UUID.randomUUID(),t.id(),f.session(),1,"SECURITY");}
 void problem(int status,Runnable r){assertEquals(status,assertThrows(Problem.class,r::run).status);}
 int count(String table,String col,UUID id){return db.queryForObject("SELECT count(*) FROM "+table+" WHERE "+col+"=?",Integer.class,id);}
 String source(Fixture f){return db.queryForObject("SELECT jsonb_build_array(to_jsonb(o),to_jsonb(t),(SELECT jsonb_agg(to_jsonb(x) ORDER BY phase) FROM order_inventory_event x WHERE order_id=o.id),(SELECT jsonb_agg(to_jsonb(x)) FROM payment_inventory_event x WHERE order_id=o.id),(SELECT jsonb_agg(to_jsonb(x) ORDER BY revision) FROM stock_revision x WHERE ticket_id=t.id))::text FROM ticket_order o JOIN ticket_type t ON t.id=o.ticket_id WHERE o.id=?",String.class,f.order().id());}
 @Test void unknownReadDoesNotApplyAndStopIsPermanentExactAndStockNeutral(){var f=fixture();var b=issue();var before=source(f);var unknown=tickets.issueReceipt(f.owner(),f.order().id(),b);assertEquals("UNKNOWN",unknown.state());assertNull(unknown.bundle());assertNull(unknown.fencedAt());assertEquals(0,count("ticket_issuance_fence","request_id",b.requestId()));var stopped=tickets.stopIssue(f.owner(),f.order().id(),b);assertEquals("FENCED",stopped.state());assertNotNull(stopped.fencedAt());assertEquals(stopped,tickets.issueReceipt(f.owner(),f.order().id(),b));assertEquals(stopped,tickets.stopIssue(f.owner(),f.order().id(),b));assertEquals(1,count("ticket_issuance_fence_audit","request_id",b.requestId()));problem(409,()->tickets.issue(f.owner(),f.order().id(),b));problem(409,()->tickets.stopIssue(f.owner(),f.order().id(),new Issue(b.requestId(),4)));assertEquals(before,source(f));assertEquals(0,count("issued_ticket","order_id",f.order().id()));assertEquals(1,tickets.issue(f.owner(),f.order().id(),issue()).tickets().size());problem(409,()->tickets.issue(f.owner(),f.order().id(),b));}
 @Test void appliedIssueLookupAndStopReturnWholeOriginalBundleNeverFence(){var f=fixture();var b=issue();var original=tickets.issue(f.owner(),f.order().id(),b);tickets.checkIn(manager,check(f,original.tickets().getFirst()));var result=tickets.stopIssue(f.owner(),f.order().id(),b);assertEquals("APPLIED",result.state());assertEquals(original.requestId(),result.bundle().requestId());assertEquals(original.tickets().getFirst().code(),result.bundle().tickets().getFirst().code());assertEquals("CHECKED_IN",result.bundle().tickets().getFirst().state());assertEquals(result,tickets.issueReceipt(f.owner(),f.order().id(),b));assertEquals(0,count("ticket_issuance_fence","request_id",b.requestId()));problem(409,()->tickets.issueReceipt(f.owner(),f.order().id(),new Issue(b.requestId(),4)));}
 @Test void recoveryWorksWithFlagsOffAndStaleBusinessVersion(){var f=fixture();var t=issued(f);var b=new Issue(UUID.randomUUID(),1);var tx=new TransactionTemplate(transactions);var off=new TicketService(db,json,false,false);assertEquals("FENCED",tx.execute(s->off.stopIssue(f.owner(),f.order().id(),b)).state());var c=check(f,t);assertEquals("FENCED",tx.execute(s->off.stopCheckIn(manager,c)).state());assertEquals("FENCED",tx.execute(s->off.checkInReceipt(manager,c)).state());assertEquals("ACTIVE",tickets.read(f.owner(),f.order().id()).tickets().getFirst().state());var done=tickets.checkIn(manager,check(f,t));assertEquals("APPLIED",tx.execute(s->off.checkInReceipt(manager,new CheckIn(done.requestId(),t.code(),f.session(),1))).state());}
 @Test void issuanceFenceBlocksAllCustomerCommandNamespacesAtSqlBoundary(){var f=fixture();var b=issue();tickets.stopIssue(f.owner(),f.order().id(),b);String before=source(f);for(String q:List.of(
  "INSERT INTO order_command VALUES('"+f.owner().id()+"','"+b.requestId()+"','ISSUE','"+"0".repeat(64)+"','"+f.order().id()+"',clock_timestamp())",
  "INSERT INTO purchase_command VALUES('"+f.owner().id()+"','"+b.requestId()+"','SUBMIT','"+"0".repeat(64)+"','"+UUID.randomUUID()+"',clock_timestamp())",
  "INSERT INTO stock_hold_intent(id,customer_id,request_id,ticket_id,generation,source_revision,quantity,ticket_version,total_twd,session_version,session_hash,fingerprint,claim_fingerprint,created_at,deadline_at) VALUES('"+UUID.randomUUID()+"','"+f.owner().id()+"','"+b.requestId()+"','"+f.type()+"',1,1,1,1,1200,1,'"+"0".repeat(64)+"','"+"0".repeat(64)+"','"+"0".repeat(64)+"',date_trunc('milliseconds',clock_timestamp()),date_trunc('milliseconds',clock_timestamp())+interval '30 seconds')")){
   var e=assertThrows(DataIntegrityViolationException.class,()->db.execute(q));assertTrue(e.getMostSpecificCause().getMessage().contains("Customer request permanently fenced"));}
  assertEquals(before,source(f));var otherOwner=fixture();assertEquals(1,tickets.issue(otherOwner.owner(),otherOwner.order().id(),b).tickets().size());}
 @Test void existingOtherCommandOrOwnerCannotBeStoppedOrDisclosed(){var f=fixture();var otherOwner=fixture();var b=new Issue(f.order().requestId(),3);problem(409,()->tickets.stopIssue(f.owner(),f.order().id(),b));assertEquals(0,count("ticket_issuance_fence","request_id",b.requestId()));problem(404,()->tickets.stopIssue(otherOwner.owner(),f.order().id(),issue()));problem(404,()->tickets.issueReceipt(otherOwner.owner(),f.order().id(),issue()));db.update("UPDATE customer_account SET enabled=false WHERE id=?",f.owner().id());problem(401,()->tickets.stopIssue(f.owner(),f.order().id(),issue()));}
 @Test void concurrentIssueAndStopChooseAppliedOrFencedWithoutDualEvidence()throws Exception{var f=fixture();var b=issue();try(var pool=Executors.newFixedThreadPool(2)){var start=new CountDownLatch(1);var apply=pool.submit(()->{start.await();try{tickets.issue(f.owner(),f.order().id(),b);return true;}catch(Problem p){assertEquals("REQUEST_FENCED",p.code);return false;}});var stop=pool.submit(()->{start.await();return tickets.stopIssue(f.owner(),f.order().id(),b);});start.countDown();boolean applied=apply.get(15,TimeUnit.SECONDS);assertEquals(applied?"APPLIED":"FENCED",stop.get(15,TimeUnit.SECONDS).state());assertEquals(applied?1:0,count("ticket_issuance","order_id",f.order().id()));assertEquals(applied?0:1,count("ticket_issuance_fence","request_id",b.requestId()));}}
 @Test void wrongSessionCheckInCanStopWithoutTouchingTicketAndCannotChangeBody()throws Exception{var f=fixture();var t=issued(f);var c=new CheckIn(UUID.randomUUID(),t.code(),UUID.randomUUID(),1);problem(409,()->tickets.checkIn(manager,c));String before=source(f);assertEquals("UNKNOWN",tickets.checkInReceipt(manager,c).state());var stopped=tickets.stopCheckIn(manager,c);assertEquals("FENCED",stopped.state());assertEquals(stopped,tickets.stopCheckIn(manager,c));assertEquals(stopped,tickets.checkInReceipt(manager,c));assertEquals(before,source(f));assertEquals("ACTIVE",tickets.read(f.owner(),f.order().id()).tickets().getFirst().state());assertEquals(1,count("ticket_admission_fence_audit","request_id",c.requestId()));assertFalse(json.writeValueAsString(stopped).contains(t.code()));problem(409,()->tickets.checkIn(manager,new CheckIn(c.requestId(),t.code(),f.session(),1)));problem(409,()->tickets.checkInReceipt(manager,new CheckIn(c.requestId(),t.code(),f.session(),1)));problem(404,()->tickets.stopCheckIn(other,c));assertEquals("CHECKED_IN",tickets.checkIn(manager,check(f,t)).ticket().state());}
 @Test void appliedCheckInStopReturnsOriginalEffectAndEnforcesActorBodyRole(){var f=fixture();var t=issued(f);var c=check(f,t);var r=tickets.checkIn(manager,c);assertEquals(r,tickets.stopCheckIn(manager,c).receipt());assertEquals("APPLIED",tickets.checkInReceipt(manager,c).state());assertEquals(0,count("ticket_admission_fence","request_id",c.requestId()));problem(404,()->tickets.checkInReceipt(other,c));problem(409,()->tickets.stopCheckIn(manager,new CheckIn(c.requestId(),t.code(),f.session(),2)));problem(403,()->tickets.checkInReceipt(viewer,c));}
 @Test void revokeStopDoesNotRevokeAndUuidCannotBeReusedAcrossAction(){var f=fixture();var t=issued(f);var b=revoke(f,t);assertEquals("UNKNOWN",tickets.revokeReceipt(manager,b).state());assertEquals("FENCED",tickets.stopRevoke(manager,b).state());assertEquals("ACTIVE",tickets.read(f.owner(),f.order().id()).tickets().getFirst().state());problem(409,()->tickets.revoke(manager,b));problem(409,()->tickets.stopRevoke(manager,new Revoke(b.requestId(),t.id(),f.session(),1,"LOST_CODE")));problem(409,()->tickets.checkIn(manager,new CheckIn(b.requestId(),t.code(),f.session(),1)));var next=revoke(f,t);var r=tickets.revoke(manager,next);assertEquals(r,tickets.stopRevoke(manager,next).receipt());assertEquals("APPLIED",tickets.revokeReceipt(manager,next).state());}
 @Test void stopLosingRequestAfterOtherTerminalEffectIsNotAnUndo(){var f=fixture();var t=issued(f);var losing=check(f,t);tickets.revoke(other,revoke(f,t));assertEquals("UNKNOWN",tickets.checkInReceipt(manager,losing).state());assertEquals("FENCED",tickets.stopCheckIn(manager,losing).state());assertEquals("REVOKED",tickets.read(f.owner(),f.order().id()).tickets().getFirst().state());assertEquals(1,tickets.audit(viewer,t.id(),1,20).total());}
 @Test void sameAdmissionUuidStopAndApplyRaceHasExactlyOneOutcome()throws Exception{var f=fixture();var t=issued(f);var b=check(f,t);var before=source(f);try(var pool=Executors.newFixedThreadPool(2)){var start=new CountDownLatch(1);var apply=pool.submit(()->{start.await();try{tickets.checkIn(manager,b);return true;}catch(Problem p){assertEquals("REQUEST_FENCED",p.code);return false;}});var stop=pool.submit(()->{start.await();return tickets.stopCheckIn(manager,b);});start.countDown();boolean applied=apply.get(15,TimeUnit.SECONDS);assertEquals(applied?"APPLIED":"FENCED",stop.get(15,TimeUnit.SECONDS).state());assertEquals(applied?1:0,count("ticket_admission_command","request_id",b.requestId()));assertEquals(applied?0:1,count("ticket_admission_fence","request_id",b.requestId()));assertEquals(before,source(f));}}
 @Test void issuanceFenceAuditFailureRollsBackFenceAndAllowsOriginalApply(){var f=fixture();var b=issue();db.execute("ALTER TABLE ticket_issuance_fence_audit ADD CONSTRAINT e2_issue_fault CHECK(request_id<>'"+b.requestId()+"'::uuid) NOT VALID");try{assertThrows(DataIntegrityViolationException.class,()->tickets.stopIssue(f.owner(),f.order().id(),b));assertEquals("UNKNOWN",tickets.issueReceipt(f.owner(),f.order().id(),b).state());assertEquals(0,count("ticket_issuance_fence","request_id",b.requestId()));}finally{db.execute("ALTER TABLE ticket_issuance_fence_audit DROP CONSTRAINT e2_issue_fault");}assertEquals(1,tickets.issue(f.owner(),f.order().id(),b).tickets().size());}
 @Test void admissionFenceAuditFailureRollsBackFenceAndAllowsOriginalApply(){var f=fixture();var t=issued(f);var b=check(f,t);db.execute("ALTER TABLE ticket_admission_fence_audit ADD CONSTRAINT e2_admit_fault CHECK(request_id<>'"+b.requestId()+"'::uuid) NOT VALID");try{assertThrows(DataIntegrityViolationException.class,()->tickets.stopCheckIn(manager,b));assertEquals("UNKNOWN",tickets.checkInReceipt(manager,b).state());assertEquals(0,count("ticket_admission_fence","request_id",b.requestId()));}finally{db.execute("ALTER TABLE ticket_admission_fence_audit DROP CONSTRAINT e2_admit_fault");}assertEquals("CHECKED_IN",tickets.checkIn(manager,b).ticket().state());}
 @Test void directSqlCannotFenceAppliedCommandsOrApplyAfterFenceOrDeleteProof(){var f=fixture();var t=issued(f);var c=check(f,t);tickets.stopCheckIn(manager,c);UUID actor=db.queryForObject("SELECT id FROM staff_account WHERE username=?",UUID.class,manager);assertThrows(DataIntegrityViolationException.class,()->db.update("INSERT INTO ticket_admission_command(request_id,actor_id,ticket_id,session_id,expected_version,action,fingerprint) VALUES(?,?,?,?,1,'CHECK_IN',?)",c.requestId(),actor,t.id(),f.session(),"0".repeat(64)));var successful=check(f,t);tickets.checkIn(manager,successful);assertThrows(DataIntegrityViolationException.class,()->db.update("INSERT INTO ticket_admission_fence(request_id,actor_id,ticket_id,session_id,expected_version,action,fingerprint) VALUES(?,?,?,?,1,'CHECK_IN',?)",successful.requestId(),actor,t.id(),f.session(),"0".repeat(64)));var b=issue();tickets.stopIssue(f.owner(),f.order().id(),b);for(var table:List.of("ticket_issuance_fence","ticket_issuance_fence_audit","ticket_admission_fence","ticket_admission_fence_audit"))assertThrows(DataIntegrityViolationException.class,()->db.update("DELETE FROM "+table+" WHERE request_id=?",table.contains("issuance")?b.requestId():c.requestId()));}
 @Test void concurrentRepeatedStopsProduceOneIdenticalAudit()throws Exception{var f=fixture();var t=issued(f);var b=check(f,t);try(var pool=Executors.newFixedThreadPool(6)){var jobs=new ArrayList<Callable<AdmissionRecovery>>();for(int i=0;i<6;i++)jobs.add(()->tickets.stopCheckIn(manager,b));AdmissionRecovery first=null;for(var future:pool.invokeAll(jobs)){var result=future.get();if(first==null)first=result;else assertEquals(first,result);}}assertEquals(1,count("ticket_admission_fence_audit","request_id",b.requestId()));assertEquals("ACTIVE",tickets.read(f.owner(),f.order().id()).tickets().getFirst().state());}
 @Test void receiptAndStopHttpRequireCsrfCurrentExpectedIdentityStrictBody()throws Exception{var f=fixture();var t=issued(f);String path="/api/customer/orders/"+f.order().id()+"/tickets/stop";var b=issue();mvc.perform(post(path).contentType("application/json").content(json.writeValueAsString(b))).andExpect(status().isForbidden());mvc.perform(post(path).cookie(new Cookie("TICKET_CUSTOMER_SESSION",f.token())).contentType("application/json").content(json.writeValueAsString(b))).andExpect(status().isForbidden());var tokenResult=mvc.perform(get("/api/customer/auth/csrf")).andReturn();var token=json.readTree(tokenResult.getResponse().getContentAsString());var cookie=tokenResult.getResponse().getCookie("TICKET_CUSTOMER_CSRF");mvc.perform(post(path).cookie(new Cookie("TICKET_CUSTOMER_SESSION",f.token()),cookie).header(token.get("headerName").asText(),token.get("token").asText()).header("X-Expected-Customer-ID",UUID.randomUUID()).contentType("application/json").content(json.writeValueAsString(b))).andExpect(status().isUnauthorized());mvc.perform(post(path).cookie(new Cookie("TICKET_CUSTOMER_SESSION",f.token()),cookie).header(token.get("headerName").asText(),token.get("token").asText()).contentType("application/json").content("{\"requestId\":\""+b.requestId()+"\",\"expectedVersion\":3,\"owner\":\"spoof\"}")).andExpect(status().isBadRequest());for(String suffix:List.of("receipt","stop")){String staffPath="/api/admin/admissions/check-ins/"+suffix;var staff=user(manager).authorities(()->"CATALOG_READ",()->"CATALOG_WRITE");mvc.perform(post(staffPath).with(staff).contentType("application/json").content(json.writeValueAsString(check(f,t)))).andExpect(status().isForbidden());mvc.perform(post(staffPath).with(staff).with(csrf()).header("X-Expected-Staff-Username",other).contentType("application/json").content(json.writeValueAsString(check(f,t)))).andExpect(status().isUnauthorized());mvc.perform(post(staffPath).with(user(viewer).authorities(()->"CATALOG_READ")).with(csrf()).contentType("application/json").content(json.writeValueAsString(check(f,t)))).andExpect(status().isForbidden());}assertEquals(0,count("ticket_issuance_fence","request_id",b.requestId()));}
 void waitForSqlLock(String table){for(int i=0;i<100;i++){db.execute("SELECT pg_stat_clear_snapshot()");if(db.queryForObject("SELECT count(*) FROM pg_stat_activity WHERE datname=current_database() AND wait_event_type='Lock' AND query LIKE ?",Integer.class,"%INSERT INTO "+table+"%")>0)return;try{Thread.sleep(30);}catch(InterruptedException e){throw new AssertionError(e);}}fail("Actual command SQL lock wait required");}
 @Test void directLateSqlWaitsForUncommittedIssueFenceThenRejects()throws Exception{var f=fixture();var b=issue();try(var pool=Executors.newSingleThreadExecutor()){
  var future=new TransactionTemplate(transactions).execute(s->{tickets.stopIssue(f.owner(),f.order().id(),b);var late=pool.submit(()->db.update("INSERT INTO order_command(customer_id,request_id,action,fingerprint,order_id) VALUES(?,?,'ISSUE',?,?)",f.owner().id(),b.requestId(),"0".repeat(64),f.order().id()));waitForSqlLock("order_command");assertFalse(late.isDone());return late;});
  var error=assertThrows(ExecutionException.class,()->future.get(10,TimeUnit.SECONDS));assertInstanceOf(DataIntegrityViolationException.class,error.getCause());assertTrue(error.getCause().getMessage().contains("permanently fenced"));
 }assertEquals(0,count("ticket_issuance","order_id",f.order().id()));assertEquals("FENCED",tickets.issueReceipt(f.owner(),f.order().id(),b).state());}
 @Test void directLateSqlWaitsForUncommittedAdmissionFenceThenRejects()throws Exception{var f=fixture();var t=issued(f);var b=check(f,t);UUID actor=db.queryForObject("SELECT id FROM staff_account WHERE username=?",UUID.class,manager);try(var pool=Executors.newSingleThreadExecutor()){
  var future=new TransactionTemplate(transactions).execute(s->{tickets.stopCheckIn(manager,b);var late=pool.submit(()->db.update("INSERT INTO ticket_admission_command(request_id,actor_id,ticket_id,session_id,expected_version,action,fingerprint) VALUES(?,?,?,?,1,'CHECK_IN',?)",b.requestId(),actor,t.id(),f.session(),"0".repeat(64)));waitForSqlLock("ticket_admission_command");assertFalse(late.isDone());return late;});
  var error=assertThrows(ExecutionException.class,()->future.get(10,TimeUnit.SECONDS));assertInstanceOf(DataIntegrityViolationException.class,error.getCause());assertTrue(error.getCause().getMessage().contains("permanently fenced"));
 }assertEquals("ACTIVE",tickets.read(f.owner(),f.order().id()).tickets().getFirst().state());assertEquals("FENCED",tickets.checkInReceipt(manager,b).state());}

}
